// Helper: single Simpson rule on [l,r] with 3 points
auto simpson3 = [](FunctionPtr f, double l, double m, double r) -> double {
    return (r - l) / 6.0 * (f(l) + 4.0 * f(m) + f(r));
};

// Recursive adaptive core
std::function<double(double,double,double,double,double,double)> adapt;
adapt = [&adapt, f, precision](double l, double r, double fl, double fm, double fr, double whole) -> double {
    double m  = (l + r) * 0.5;
    double lm = (l + m) * 0.5;
    double rm = (m + r) * 0.5;

    double flm = f(lm);
    double frm = f(rm);

    double left  = simpson3(f, l, lm, m);
    double right = simpson3(f, m, rm, r);
    double refined = left + right;

    if (std::abs(refined - whole) <= 15.0 * precision)   // error < tol
        return refined + (refined - whole) / 15.0;         // Richardson extrapolation
    return adapt(l, m, fl, flm, fm, left) +
           adapt(m, r, fm, frm, fr, right);
};

double m = (a + b) * 0.5;
double fa = f(a);
double fb = f(b);
double fm = f(m);
double whole = simpson3(f, a, m, b);

return adapt(a, b, fa, fm, fb, whole);

